def adopt_api_verification(
    apps: StateApps,
    schema_editor: BaseDatabaseSchemaEditor,  # ruff: ignore[unused-function-argument]
) -> None:
    ApiUser = apps.get_model("apiauth", "ApiUser")
    CodigoVerificacion = apps.get_model("rudiauth", "CodigoVerificacion")
    RudiUser = apps.get_model("rudiauth", "RudiUser")
    VerificationCode = apps.get_model("apiauth", "VerificationCode")

    # the address belongs to the account, so its verification does too
    verified = RudiUser.objects.filter(email_verified_at__isnull=False).values_list(
        "user_id",
        "email_verified_at",
    )

    for user_id, verified_at in verified:
        ApiUser.objects.filter(email_verified_at__isnull=True, pk=user_id).update(
            email_verified_at=verified_at,
        )

    # links already in someone's inbox keep working
    live = CodigoVerificacion.objects.select_related("user").filter(
        consumido_at__isnull=True,
        expira_at__gt=timezone.now(),
        invalidado_at__isnull=True,
        user__isnull=False,
    )

    VerificationCode.objects.bulk_create(
        VerificationCode(
            api_user_id=codigo.user.user_id,
            created_at=codigo.created_at,
            email=codigo.email,
            expires_at=codigo.expira_at,
            purpose=PURPOSES[codigo.proposito],
            token_hash=codigo.token_hash,
        )
        for codigo in live
    )


